// 开源广场《让界面动得像 iPhone》的三个试玩：弹簧、程序坞放大、共享元素转场。
// 跑的就是网站自己在用的那几段（motion.js 的 spring / springEase / transition，dock-math.js），不另写一套。
// mode：'try' 能拖能点；'watch' 自己演（精选里只播不操作）。只动 transform / opacity。
import { SPRINGS, spring, springEase, transition, reducedMotion } from './motion.js';
import { dockLayout, dockTargets } from './dock-math.js';
import { appIcon } from './app-icons.js';

const PRESET = { smooth: '平稳', snappy: '干脆', bouncy: '弹跳', interactive: '跟手' };

/** 把试玩挂到 root 上；返回 { destroy } */
export function mountDemo(root, name, { mode = 'try' } = {}) {
  const make = { spring: springDemo, dock: dockDemo, morph: morphDemo }[name];
  if (!make) return { destroy() {} };
  return make(root, mode === 'watch');
}

// 自己演的循环：页面在后台或被摘下时停
function loop(root, step) {
  let timer = 0, dead = false;
  const tick = async () => {
    if (dead || !root.isConnected) return;
    const wait = document.hidden ? 800 : await step();
    if (!dead) timer = setTimeout(tick, wait);
  };
  timer = setTimeout(tick, 500);
  return () => { dead = true; clearTimeout(timer); };
}

