function springDemo(root, watch) {
  root.innerHTML = `
    <div class="md md-spring">
      <div class="md-track"${watch ? '' : ' role="button" tabindex="0" aria-label="让方块弹到另一头"'}><i class="md-rail"></i><b class="md-ball"></b></div>
      <svg class="md-plot" viewBox="0 0 320 120" aria-hidden="true"><path class="md-plot-grid" d="M0 100H320M0 30H320"/><path class="md-plot-curve"/><circle class="md-plot-dot" r="5" cx="0" cy="0"/></svg>
      <p class="md-read"><b data-name></b><span data-params></span><span data-dur></span></p>
      ${watch ? '' : `<div class="md-controls">
        <div class="as-seg md-presets" role="group" aria-label="网站在用的四组弹簧"><i class="as-seg-thumb" aria-hidden="true"></i>${Object.keys(SPRINGS).map((k) => `<button type="button" data-preset="${k}">${PRESET[k]}</button>`).join('')}</div>
        <label class="md-slider"><span>response</span><input type="range" min="0.15" max="1.2" step="0.01" data-k="response"><output data-out="response"></output></label>
        <label class="md-slider"><span>damping</span><input type="range" min="0.3" max="1" step="0.01" data-k="damping"><output data-out="damping"></output></label>
      </div>`}
    </div>`;
  const $ = (s) => root.querySelector(s);
