    $('[data-params]').textContent = `response ${params.response.toFixed(2)} · damping ${params.damping.toFixed(2)}`;
    $('[data-dur]').textContent = `${Math.round(duration * 1000)} ms${peak > 1.001 ? ` · 过冲 ${((peak - 1) * 100).toFixed(1)}%` : ' · 不回弹'}`;
    root.querySelectorAll('[data-k]').forEach((input) => { input.value = params[input.dataset.k]; });
    root.querySelectorAll('[data-out]').forEach((o) => { o.textContent = params[o.dataset.out].toFixed(2); });
    const seg = $('.md-presets');
    if (seg) {
      const i = Object.keys(SPRINGS).indexOf(name);
      seg.style.setProperty('--i', String(Math.max(0, i)));
      seg.querySelectorAll('button').forEach((b) => b.setAttribute('aria-pressed', String(b.dataset.preset === name)));
      seg.classList.toggle('is-off', i < 0);
    }
  };

  // 方块用 spring() 的 linear() 缓动跑（和网站换页、弹窗同一条曲线）；曲线上的小点跟着动画走
  const play = () => {
    const travel = track.clientWidth - ball.offsetWidth;
    side = 1 - side;
    const from = side ? 0 : travel, to = side ? travel : 0;
    run?.cancel();
    cancelAnimationFrame(frame);
    if (reducedMotion()) { ball.style.transform = `translateX(${to}px)`; return Promise.resolve(); }
    const s = spring(params), { ease } = springEase(params);
    run = ball.animate([{ transform: `translateX(${from}px)` }, { transform: `translateX(${to}px)` }], { duration: s.duration, easing: s.easing, fill: 'forwards' });
    const anim = run;
    const follow = () => {
      const p = Math.min(1, (anim.currentTime ?? 0) / s.duration);
      dot.style.transform = `translate(${(p * 320).toFixed(1)}px, ${(100 - ease(p) * 70).toFixed(1)}px)`;
      if (p < 1 && anim.playState === 'running') frame = requestAnimationFrame(follow);
    };
    frame = requestAnimationFrame(follow);
    return anim.finished.catch(() => {});
  };

  draw();
  dot.style.transform = 'translate(0px, 100px)';
  if (watch) {
    const names = Object.keys(SPRINGS);
    let k = 0;
    const stop = loop(root, async () => {
      name = names[k++ % names.length];
      params = { ...SPRINGS[name] };
      draw();
      await play();
      return 900;
    });
    return { destroy() { stop(); run?.cancel(); cancelAnimationFrame(frame); } };
  }
  track.addEventListener('click', play);
  track.addEventListener('keydown', (e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); play(); } });
  root.addEventListener('click', (e) => {
    const b = e.target.closest('[data-preset]');
    if (!b) return;
    name = b.dataset.preset;
    params = { ...SPRINGS[name] };
    draw();
    play();
  });
  root.addEventListener('input', (e) => {
    const k = e.target.dataset?.k;
    if (!k) return;
    params = { ...params, [k]: Number(e.target.value) };
    name = Object.keys(SPRINGS).find((n) => SPRINGS[n].response === params.response && SPRINGS[n].damping === params.damping) || '';
    draw();
  });
  root.addEventListener('change', (e) => { if (e.target.dataset?.k) play(); });
  return { destroy() { run?.cancel(); cancelAnimationFrame(frame); } };
}

/* ---------------- 程序坞放大 ---------------- */

const DOCK_ICONS = ['clock', 'study', 'seat', 'pin', 'post', 'exam', 'bag', 'trophy', 'upload'];

function dockDemo(root, watch) {
  root.innerHTML = `
    <div class="md md-dock">
      <p class="md-hint">${watch ? '自动演示：一个看不见的指针在程序坞上来回划' : '把鼠标放到程序坞上，左右划'}</p>
      <div class="md-dockbar">
        <i class="md-dock-bg" aria-hidden="true"></i>
        ${DOCK_ICONS.map((n) => `<span class="md-dock-item">${appIcon(n)}</span>`).join('')}
        ${watch ? '<i class="md-cursor" aria-hidden="true"></i>' : ''}
      </div>
      ${watch ? '' : `<div class="md-controls">
        <label class="md-slider"><span>放大到</span><input type="range" min="0" max="1.2" step="0.05" data-k="max"><output data-out="max"></output></label>
        <label class="md-slider"><span>影响范围</span><input type="range" min="60" max="260" step="10" data-k="range"><output data-out="range"></output></label>
      </div>`}
    </div>`;
  const bar = root.querySelector('.md-dockbar'), bg = root.querySelector('.md-dock-bg'), cursor = root.querySelector('.md-cursor');
  const opts = { max: 0.5, range: 140 };   // 和左边拓展坞同一组数
  let items = [], cur = [], target = [], pointer = null, frame = 0, last = 0, width = 0, sweep = 0;
  const measure = () => {
    items = [...bar.querySelectorAll('.md-dock-item')].map((el) => ({ el, start: el.offsetLeft, size: el.offsetWidth, grow: true }));
    width = bar.offsetWidth;
    cur = items.map((_, i) => cur[i] ?? 1);
    target = items.map((_, i) => target[i] ?? 1);
  };
  const show = () => {
    root.querySelectorAll('[data-k]').forEach((input) => { input.value = opts[input.dataset.k]; });
    root.querySelectorAll('[data-out]').forEach((o) => { o.textContent = o.dataset.out === 'max' ? `${(1 + opts.max).toFixed(2)} 倍` : `${opts.range} px`; });
  };
  // 和 shell.js initDock 一样：每帧向目标值指数逼近（60ms 时间常数），排开的位置交给 dockLayout
  const paint = (now) => {
    frame = 0;
    if (!root.isConnected) return;
    if (!width) measure();
    const dt = last ? Math.min(64, now - last) : 16;
    last = now;
    const a = 1 - Math.exp(-dt / 60);
    let moving = false;
    items.forEach((_, i) => {
      cur[i] += (target[i] - cur[i]) * a;
      if (Math.abs(target[i] - cur[i]) < 0.002) cur[i] = target[i]; else moving = true;
    });
    const { shifts, total, anchor } = dockLayout(items, cur, pointer);
    items.forEach((it, i) => { it.el.style.transform = `translateX(${shifts[i].toFixed(2)}px) scale(${cur[i].toFixed(4)})`; });
    bg.style.transform = `translateX(${(-anchor).toFixed(2)}px) scaleX(${((width + total) / width).toFixed(4)})`;
    if (moving || watch) frame = requestAnimationFrame(paint); else last = 0;
    if (watch) drive(now);
  };
  const kick = () => { if (!frame) frame = requestAnimationFrame(paint); };
  const point = (x) => { pointer = x; target = x == null ? items.map(() => 1) : dockTargets(items, x, opts); kick(); };
  // 自动演示：指针按正弦来回扫，扫到两头停一下再回来
  const drive = (now) => {
    if (!sweep) sweep = now;
    const p = ((now - sweep) / 4200) % 1;
    const x = width / 2 + Math.sin(p * Math.PI * 2) * (width / 2 - 20);
    cursor.style.transform = `translate(${x.toFixed(1)}px, -50%)`;
    pointer = x;
    target = dockTargets(items, x, opts);
  };
  measure();
  show();
  if (watch) {
    if (reducedMotion()) return { destroy() {} };
    kick();
    return { destroy() { cancelAnimationFrame(frame); frame = -1; } };
  }
  const ro = new ResizeObserver(() => { items.forEach((it) => (it.el.style.transform = '')); measure(); point(null); });
  ro.observe(bar);
  bar.addEventListener('pointermove', (e) => {
    if (reducedMotion() || e.pointerType !== 'mouse') return;
    point(e.clientX - bar.getBoundingClientRect().left);
  });
  bar.addEventListener('pointerleave', () => point(null));
  root.addEventListener('input', (e) => {
    const k = e.target.dataset?.k;
    if (!k) return;
    opts[k] = Number(e.target.value);
    show();
    if (pointer != null) point(pointer);
  });
  return { destroy() { ro.disconnect(); cancelAnimationFrame(frame); } };
}

