function morphDemo(root, watch) {
  root.innerHTML = `
    <div class="md md-morph">
      <div class="md-cards">${CARDS.map((c, i) => `<button type="button" class="md-card" style="--h:${c.h}" data-i="${i}"${watch ? ' tabindex="-1"' : ''}><small>${c.k}</small><b>${c.t}</b></button>`).join('')}</div>
      <div class="md-detail" hidden>
        <div class="md-sheet" role="dialog" aria-label="展开的卡片">
          <div class="md-sheet-head"><small></small><b></b></div>
          <div class="md-sheet-body"><i></i><i></i><i></i><i></i></div>
          <button type="button" class="md-close" aria-label="收起"${watch ? ' tabindex="-1"' : ''}>×</button>
        </div>
      </div>
      <p class="md-hint">${watch ? '自动演示：点开一张卡片，再收回去' : '点一张卡片，它从原位长成详情；再点 × 收回去'}</p>
    </div>`;
  const detail = root.querySelector('.md-detail'), sheet = root.querySelector('.md-sheet');
  let open = null;
  const fill = (i) => {
    sheet.style.setProperty('--h', CARDS[i].h);
    sheet.querySelector('small').textContent = CARDS[i].k;
    sheet.querySelector('b').textContent = CARDS[i].t;
  };
  const cardOf = (i) => root.querySelector(`.md-card[data-i="${i}"]`);

  // 点着玩：用网站的 transition()（View Transitions），卡片和详情同名，浏览器自己补间
  const swap = (i) => transition(() => {
    if (i != null) {
      cardOf(i).style.viewTransitionName = '';
      fill(i);
      detail.hidden = false;
      sheet.style.viewTransitionName = 'md-card';
      cardOf(i).style.visibility = 'hidden';
    } else {
      sheet.style.viewTransitionName = '';
      detail.hidden = true;
      cardOf(open).style.visibility = '';
      cardOf(open).style.viewTransitionName = 'md-card';
    }
  }, 'morph').then(() => { root.querySelectorAll('.md-card').forEach((c) => (c.style.viewTransitionName = '')); });

  // 自己演：精选里不能占用整页的转场，同一条弹簧手动

